import React, { ReactNode } from 'react';
import { isElement } from 'react-is';
import { TableInstance } from 'react-table';

import { Pagination } from './Pagination.js';
import { TablePaginationContext } from '../../contexts/TablePaginationContext.js';

type DataTablePaginationProps = {
  children: ReactNode;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  instance: TableInstance<any>;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  data: any[];
};

export const DataTablePagination = (props: DataTablePaginationProps) => {
  const { children, instance, data } = props;

  const {
    canNextPage,
    canPreviousPage,
    pageCount,
    manualPagination,
    state: { pageIndex, pageSize },
    setPageIndex,
    setPageSize,
  } = instance;

  const renderFallback = !isElement(children) && pageSize !== undefined;

  return (
    <TablePaginationContext.Provider
      value={{
        canPreviousPage,
        canNextPage,
        pageCount,
        pageSize,
        pageIndex,
        setPageSize,
        setPageIndex,
        manualPagination,
        data,
      }}
    >
      {renderFallback ? (
        <Pagination defaultPageSize={pageSize} defaultPageIndex={pageIndex} />
      ) : (
        children
      )}
    </TablePaginationContext.Provider>
  );
};
